### 4. Low-Latency Matching Engine Core (C++ / Ring Buffer Implementation)

The core engine runs in user-space, bypassing OS kernel overhead via lock-free ring buffers (LMAX Disruptor pattern).

```cpp
#include <iostream>
#include <atomic>
#include <cstdint>
#include <vector>
#include <map>

// Fixed-point representation for deterministic math (8 decimal places)
using Price = uint64_t;
using Quantity = uint64_t;
using OrderId = uint64_t;

enum class Side { BUY, SELL };
enum class OrderType { LIMIT, MARKET };

struct Order {
    OrderId id;
    Side side;
    Price price;
    Quantity qty;
    uint64_t hlc_physical;
    uint32_t hlc_logical;
};

struct Trade {
    OrderId buy_order_id;
    OrderId sell_order_id;
    Price execution_price;
    Quantity execution_qty;
};

class OrderBook {
private:
    // Price-time priority queues
    std::map<Price, std::vector<Order>, std::greater<Price>> bids_; // Highest price first
    std::map<Price, std::vector<Order>, std::less<Price>> asks_;    // Lowest price first

public:
    std::vector<Trade> process_order(Order order) {
        std::vector<Trade> trades;

        if (order.side == Side::BUY) {
            while (order.qty > 0 && !asks_.empty() && asks_.begin()->first <= order.price) {
                auto& best_ask_queue = asks_.begin()->second;
                auto& resting_order = best_ask_queue.front();

                Quantity matched_qty = std::min(order.qty, resting_order.qty);
                trades.push_back({order.id, resting_order.id, asks_.begin()->first, matched_qty});

                order.qty -= matched_qty;
                resting_order.qty -= matched_qty;

                if (resting_order.qty == 0) {
                    best_ask_queue.erase(best_ask_queue.begin());
                    if (best_ask_queue.empty()) {
                        asks_.erase(asks_.begin());
                    }
                }
            }
            if (order.qty > 0) {
                bids_[order.price].push_back(order);
            }
        } else {
            while (order.qty > 0 && !bids_.empty() && bids_.begin()->first >= order.price) {
                auto& best_bid_queue = bids_.begin()->second;
                auto& resting_order = best_bid_queue.front();

                Quantity matched_qty = std::min(order.qty, resting_order.qty);
                trades.push_back({resting_order.id, order.id, bids_.begin()->first, matched_qty});

                order.qty -= matched_qty;
                resting_order.qty -= matched_qty;

                if (resting_order.qty == 0) {
                    best_bid_queue.erase(best_bid_queue.begin());
                    if (best_bid_queue.empty()) {
                        bids_.erase(bids_.begin());
                    }
                }
            }
            if (order.qty > 0) {
                asks_[order.price].push_back(order);
            }
        }
        return trades;
    }
};

// Ring Buffer Ring Node
struct RingBufferNode {
    std::atomic<bool> sequence_ready{false};
    Order order;
};

template <size_t Size>
class LockFreeRingBuffer {
    RingBufferNode buffer_[Size];
    std::atomic<uint64_t> head_{0};
    std::atomic<uint64_t> tail_{0};

public:
    bool push(const Order& order) {
        uint64_t current_tail = tail_.load(std::memory_order_relaxed);
        uint64_t current_head = head_.load(std::memory_order_acquire);

        if (current_tail - current_head >= Size) {
            return false; // Buffer full
        }

        buffer_[current_tail % Size].order = order;
        buffer_[current_tail % Size].sequence_ready.store(true, std::memory_order_release);
        tail_.store(current_tail + 1, std::memory_order_release);
        return true;
    }

    bool pop(Order& order) {
        uint64_t current_head = head_.load(std::memory_order_relaxed);
        uint64_t current_tail = tail_.load(std::memory_order_acquire);

        if (current_head == current_tail) {
            return false; // Buffer empty
        }

        if (!buffer_[current_head % Size].sequence_ready.load(std::memory_order_acquire)) {
            return false; // Not yet written by producer
        }

        order = buffer_[current_head % Size].order;
        buffer_[current_head % Size].sequence_ready.store(false, std::memory_order_release);
        head_.store(current_head + 1, std::memory_order_release);
        return true;
    }
};
```

